int get_pppol2tp_sock_ops(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    struct sock *sk = sock->sk;
    int len = 0;

    if (!sk)
        return -EINVAL;

    if (!sk->sk_state)
        return -ENOTCONN;

    struct pppol2tp_session *session = sk->sk_user_data;
    if (!session)
        return -ENOENT;

    if (session->session_id) {
        /* Retrieve session options */
        len = session->session_options_len;
    } else {
        /* Retrieve tunnel options */
        len = session->tunnel_options_len;
    }

    if (len < 0)
        return -EFAULT;

    if (copy_to_user(optval, &len, len))
        return -EFAULT;

    if (put_user(len, optlen))
        return -EFAULT;

    return 0;
}

int getsockopt_pppox_l2tp(struct socket *sock, int level, int optname,
                          char __user *optval, int __user *optlen)
{
    struct sock *sk = sock->sk;
    struct pppox_sock *po = pppox_sk(sk);
    struct pppol2tp_session *s;
    int len, ret;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (get_user(len, optlen))
        return -EFAULT;

    if (len < 0)
        return -EINVAL;

    if (!po->session_id)
        return -ENOTCONN;

    s = pppol2tp_find_session(sk);
    if (!s)
        return -ENOENT;

    if (s->session_id)
        ret = pppol2tp_get_session_opt(s, optname, optval, optlen);
    else
        ret = pppol2tp_get_tunnel_opt(s, optname, optval, optlen);

    if (ret < 0)
        return ret;

    return 0;
}

int get_pppol2tpsockopt(struct socket *sock, int level, int optname,
                        char __user *optval, int __user *optlen)
{
    int len;
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    struct pppol2tp_tunnel *tunnel;
    int val;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (get_user(len, optlen))
        return -EFAULT;

    if (len < 0)
        return -EINVAL;

    if (!sk->sk_state == PPPOX_CONNECTED)
        return -ENOTCONN;

    session = pppol2tp_get_session(sk);
    if (!session)
        return -ENOENT;

    if (session->session_id == 0) {
        tunnel = pppol2tp_get_tunnel(sk);
        if (!tunnel)
            return -ENOENT;

        switch (optname) {
            case PPPOLOPT_DEBUG:
                val = tunnel->debug;
                break;
            default:
                pppol2tp_put_tunnel(tunnel);
                return -ENOPROTOOPT;
        }
        pppol2tp_put_tunnel(tunnel);
    } else {
        switch (optname) {
            case PPPOLOPT_DEBUG:
                val = session->debug;
                break;
            default:
                pppol2tp_put_session(session);
                return -ENOPROTOOPT;
        }
        pppol2tp_put_session(session);
    }

    if (put_user(sizeof(val), optlen))
        return -EFAULT;

    if (copy_to_user(optval, &val, sizeof(val)))
        return -EFAULT;

    return 0;
}

int get_pppol2tpsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    int ret = 0;
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (sock->state != SS_CONNECTED)
        return -ENOTCONN;

    session = pppol2tp_get_session(sk);
    if (!session)
        return -ENOENT;

    switch (optname) {
    case PPPOLOPT_TUNNEL_ID:
        if (session->tunnel)
            ret = put_user(session->tunnel->tunnel_id, (u32 __user *)optval);
        else
            ret = -ENOENT;
        break;
    case PPPOLOPT_SESSION_ID:
        ret = put_user(session->session_id, (u32 __user *)optval);
        break;
    default:
        ret = -EINVAL;
    }

    if (ret == 0 && optlen != NULL)
        put_user(4, optlen);

    return ret;
}

int pppol2tp_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    int len;
    int val;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (get_user(len, optlen))
        return -EFAULT;

    if (len < 0)
        return -EINVAL;

    if (!sock->sk->sk_state || !sock->sk->sk_state != PPPOX_CONNECTED)
        return -ENOTCONN;

    session = pppol2tp_get_session(sk);
    if (!session)
        return -ENOENT;

    if (session->session_id == 0) {
        val = session->tunnel->options;
    } else {
        val = session->options;
    }

    if (put_user(val, optval))
        return -EFAULT;

    if (put_user(sizeof(val), optlen))
        return -EFAULT;

    return 0;
}
